export function filterProducts(category = 'all') {
  return category === 'all' ? [...products] : products.filter(p => p.category === category);
}

export function createBrief(fields) {
  return `${site.company} — Packaging project brief\n\nName: ${fields.name || ''}\nEmail: ${fields.email || ''}\nCompany: ${fields.company || 'Not specified'}\nPackaging: ${fields.product || 'Please advise'}\nQuantity: ${fields.quantity || 'To discuss'}\n\nProject details\n${fields.message || ''}\n\nThis brief has not been sent. Please share it with your packaging contact.\n`;
}

